import React, { useEffect } from "react";
import { useSelector, useDispatch } from "react-redux";
import { fetchUser } from "../Features/UserSlice";
import "../Styles/UserProfile.css";

const UserProfile = () => {
  const dispatch = useDispatch();
  const { user, isLoading, isError } = useSelector((state) => state.users);

  // Logout function to clear user session and navigate to login
  const handleLogout = async () => {
    // Remove all saved session data
    localStorage.removeItem("role");
    localStorage.removeItem("loggedUser");
    localStorage.removeItem("applications");

    // Also reset Redux state
    dispatch(logout());

    // Small delay before navigation
    await new Promise((resolve) => setTimeout(resolve, 100));
    navigate("/login");
  };

  useEffect(() => {
    // Get the user's email from Redux or localStorage
    const email =
      user?.email || JSON.parse(localStorage.getItem("loggedUser"))?.email;

    // Fetch user data from MongoDB using the email
    if (email) {
      dispatch(fetchUser(email));
    }
  }, [dispatch]);

  // Show loading message while fetching data
  if (isLoading) return <p>Loading user info...</p>;

  // Show error message if request fails
  if (isError) return <p>Error loading profile</p>;

  // Show this if user data does not exist
  if (!user) return <p>No user found.</p>;

  return (
    <div className="profile-page">
      {/* Main user profile card */}
      <div className="profile-card">
        <div className="profile-left">
          <div className="profile-icon">👤</div>
          <div>
            {/* Display basic user info */}
            <h2 className="profile-name">{user.name}</h2>
            <p className="profile-email">{user.email}</p>
            <p className="profile-detail">
              {user.major} • Age: {user.age} • {user.role}
            </p>
          </div>
        </div>
      </div>

      {/* Placeholder for applications section */}
      <div className="history-box">
        <h3>My Applications</h3>
        <p>Feature coming soon — applications will show here.</p>
      </div>
    </div>
  );
};

export default UserProfile;
